/**
 * Gotify Node - Version 1
 * Discriminator: resource=message, operation=create
 */


interface Credentials {
  gotifyApi: CredentialReference;
}

export type GotifyV1MessageCreateParams = {
  resource: 'message';
  operation: 'create';
/**
 * The message to send, If using Markdown add the Content Type option
 */
    message: string | Expression<string>;
/**
 * Additional Fields
 * @default {}
 */
    additionalFields?: {
    /** The priority of the message
     * @default 1
     */
    priority?: number | Expression<number>;
    /** The title of the message
     */
    title?: string | Expression<string>;
  };
/**
 * Options
 * @default {}
 */
    options?: {
    /** The message content type
     * @default text/plain
     */
    contentType?: 'text/plain' | 'text/markdown' | Expression<string>;
    /** Opens this URL when the notification is clicked
     */
    clickUrl?: string | Expression<string>;
    /** Shows a big image in the notification
     */
    bigImageUrl?: string | Expression<string>;
    /** Opens an intent URL after the notification is delivered (Android only)
     */
    intentUrl?: string | Expression<string>;
  };
};

export type GotifyV1MessageCreateNode = {
  type: 'n8n-nodes-base.gotify';
  version: 1;
  config: NodeConfig<GotifyV1MessageCreateParams> & { credentials?: Credentials };
};